<script setup>
import {Head,router} from '@inertiajs/vue3';import {ref} from 'vue';import AppShell from '@/Layouts/AppShell.vue';import SettingsNav from '@/Components/SettingsNav.vue';import PageHeader from '@/Components/PageHeader.vue';
const p=defineProps({section:String,tab:String,filters:Object,transactions:Object,types:Object}),open=ref([]),form=ref({status:p.filters.status||'',type:p.filters.type||'',currency:p.filters.currency||'',search:p.filters.search||'',from:p.filters.from||'',to:p.filters.to||''});const money=(minor,currency)=>minor===null||minor===undefined?'—':new Intl.NumberFormat('en-IN',{style:'currency',currency}).format(minor/100),date=v=>new Date(v).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});function go(tab){router.get('/settings/transactions',{...form.value,tab},{preserveState:true})}function filter(){go(p.tab)}function reset(){form.value={status:'',type:'',currency:'',search:'',from:'',to:''};go(p.tab)}function toggle(id){let i=open.value.indexOf(id);i<0?open.value.push(id):open.value.splice(i,1)}function exportUrl(){let q=new URLSearchParams({...form.value,tab:p.tab});return'/settings/transactions/export?'+q}
</script>
<template><AppShell><Head title="Transactions"/><div class="lp-page"><PageHeader eyebrow="Settings" title="Transactions" description="Review account-owned payments and Wallet activity."/><div class="mt-8 grid gap-6 lg:grid-cols-[240px_1fr]"><SettingsNav :section="section"/><main class="space-y-6"><section class="lp-card p-5 sm:p-6"><div class="flex flex-wrap items-center justify-between gap-4"><div role="tablist" aria-label="Transaction categories" class="flex rounded-xl bg-slate-100 p-1"><button v-for="key in ['main','wallet']" :id="`tab-${key}`" type="button" role="tab" :aria-selected="tab===key" class="rounded-lg px-5 py-2 font-semibold capitalize" :class="tab===key?'bg-white text-indigo shadow-sm':'text-slate-600'" @click="go(key)">{{key==='main'?'Main':'Wallet'}}</button></div><a :href="exportUrl()" class="btn-secondary">Export CSV</a></div><form class="mt-5 grid gap-3 md:grid-cols-3 xl:grid-cols-6" @submit.prevent="filter"><label class="lp-label">Search<input v-model.trim="form.search" class="field mt-1" maxlength="100"></label><label class="lp-label">Status<select v-model="form.status" class="field mt-1"><option value="">All</option><option v-for="s in ['pending','processing','paid','completed','failed','cancelled','expired','refunded','partially_refunded','reversed','disputed']" :value="s">{{s.replaceAll('_',' ')}}</option></select></label><label class="lp-label">Type<select v-model="form.type" class="field mt-1"><option value="">All</option><option v-for="(label,key) in types" :value="key">{{label}}</option></select></label><label class="lp-label">Currency<input v-model.trim="form.currency" class="field mt-1 uppercase" maxlength="3" placeholder="INR"></label><label class="lp-label">From<input v-model="form.from" type="date" class="field mt-1"></label><label class="lp-label">To<input v-model="form.to" type="date" class="field mt-1"></label><div class="flex gap-2 md:col-span-3 xl:col-span-6"><button class="btn-primary">Apply Filters</button><button type="button" class="btn-secondary" @click="reset">Reset Filters</button></div></form></section>
<section class="lp-card overflow-hidden"><div v-if="transactions.data.length"><article v-for="t in transactions.data" :key="t.id" class="border-b border-slate-200 last:border-0"><button type="button" class="grid w-full items-center gap-3 p-5 text-left sm:grid-cols-[1fr_auto_auto]" :aria-expanded="open.includes(t.id)" :aria-controls="`details-${t.id}`" @click="toggle(t.id)"><span><strong class="block">{{t.description}}</strong><span class="mt-1 block text-sm text-slate-500">{{date(t.date)}} · {{t.status.replaceAll('_',' ')}}</span></span><span class="font-semibold"><template v-if="t.category==='wallet'&&t.credits">{{t.direction==='debit'?'-':'+'}}{{t.credits}} credits</template><template v-else>{{money(t.total_minor,t.currency)}}</template></span><span aria-hidden="true">{{open.includes(t.id)?'⌃':'⌄'}}</span></button><dl v-if="open.includes(t.id)" :id="`details-${t.id}`" class="grid gap-4 bg-slate-50 p-5 text-sm sm:grid-cols-2 lg:grid-cols-3"><div><dt>Transaction ID</dt><dd class="break-all font-semibold">{{t.id}}</dd></div><div><dt>Type</dt><dd class="font-semibold">{{types[t.type]||t.type}}</dd></div><div><dt>Status</dt><dd class="font-semibold capitalize">{{t.status.replaceAll('_',' ')}}</dd></div><div><dt>Currency</dt><dd class="font-semibold">{{t.currency}}</dd></div><div v-if="t.subtotal_minor!==null"><dt>Subtotal</dt><dd class="font-semibold">{{money(t.subtotal_minor,t.currency)}}</dd></div><div v-if="t.tax_minor!==null"><dt>Tax/GST</dt><dd class="font-semibold">{{money(t.tax_minor,t.currency)}}</dd></div><div v-if="t.total_minor!==null"><dt>Total</dt><dd class="font-semibold">{{money(t.total_minor,t.currency)}}</dd></div><div v-if="t.credits"><dt>Wallet credits {{t.direction==='debit'?'used':'added'}}</dt><dd class="font-semibold">{{t.credits}}</dd></div><div><dt>Payment Method</dt><dd class="font-semibold">{{t.payment_method}}</dd></div><div v-if="t.provider_reference"><dt>Provider Reference</dt><dd class="break-all font-semibold">{{t.provider_reference}}</dd></div><div v-for="(value,key) in t.details"><dt class="capitalize">{{key.replaceAll('_',' ')}}</dt><dd class="font-semibold">{{value}}</dd></div></dl></article></div><div v-else class="p-10 text-center text-slate-500">{{tab==='main'?'No main transactions found.':'No Wallet transactions found.'}}</div></section><nav class="flex flex-wrap gap-2" aria-label="Transaction pages"><a v-for="l in transactions.links" :href="l.url||'#'" class="btn-secondary" :class="{'pointer-events-none opacity-50':!l.url}" v-text="l.label"></a></nav></main></div></div></AppShell></template>
